export function HBHelp({children}:{children:ReactNode}){return <details className="hb-help"><summary aria-label="Пояснение">?</summary><div>{children}</div></details>;}
function Field({label,help,children}:{label:string;help?:string;children:ReactNode}){return <div className="hb-field"><span>{label} {help&&<HBHelp>{help}</HBHelp>}</span>{children}</div>;}
function Select({value,onChange,options,label}:{value:string;onChange:(v:string)=>void;options:Record<string,string>;label:string}){return <select aria-label={label} value={value} onChange={e=>onChange(e.target.value)}>{Object.entries(options).map(([id,name])=><option key={id} value={id}>{name}</option>)}</select>;}
function Formula({value,onChange,label='Формула'}:{value:number|string;onChange:(v:string)=>void;label?:string}){return <Field label={label} help="Переменные берутся из персонажа. Разрешены арифметика, сравнения, min/max/floor/ceil/clamp. Кости записываются как 1d8; предпросмотр показывает среднее."><input aria-label={label} value={value} onChange={e=>onChange(e.target.value)}/><details><summary>Вставить переменную</summary><div className="hb-toolbar">{vars.map(v=><button type="button" key={v} onClick={()=>onChange(String(value)+v)}>{v}</button>)}</div></details></Field>;}
