 return <section><h3>Бонусные заклинания</h3><p>Выдаются автоматически на уровне класса и не занимают лимит известных. Ограниченные применения появятся как ресурс на листе.</p><input aria-label="Поиск бонусного заклинания" value={query} onChange={e=>setQuery(e.target.value)} placeholder="Найти заклинание"/><div className="hb-toolbar">{options.map(spell=><button key={spell.id} onClick={()=>update({spellGrants:[...grants,{spellId:spell.id,level:draft.type==='subclass'?draft.subclass?.chooseAtLevel||3:1,mode:'known',countsAgainstKnown:false}]})}>+ {spell.name}</button>)}</div>{grants.map((grant,i)=><fieldset key={i} className="hb-row"><strong>{options.find(e=>e.id===grant.spellId)?.name||spells.find(e=>e.id===grant.spellId)?.name||entities.find(e=>e.id===grant.spellId)?.name||grant.spellId}</strong><Field label="С уровня класса"><input type="number" min={1} max={20} value={grant.level} onChange={e=>update({spellGrants:grants.map((g,n)=>n===i?{...g,level:Number(e.target.value)}:g)})}/></Field><Field label="Режим"><Select label="Режим заклинания" value={grant.mode||'known'} onChange={mode=>update({spellGrants:grants.map((g,n)=>n===i?{...g,mode:mode as 'known'|'always-prepared'}:g)})} options={{known:'Всегда известно', 'always-prepared':'Всегда подготовлено'}}/></Field><Field label="Применений без ячейки (0 — обычные ячейки)"><input type="number" min={0} max={20} value={grant.uses||0} onChange={e=>update({spellGrants:grants.map((g,n)=>n===i?{...g,uses:Number(e.target.value)||undefined}:g)})}/></Field>{!!grant.uses&&<Select label="Восстановление применений" value={grant.recovery||'long'} onChange={recovery=>update({spellGrants:grants.map((g,n)=>n===i?{...g,recovery:recovery as 'long'|'short_or_long'}:g)})} options={{long:'Длинный отдых',short_or_long:'Короткий или длинный'}}/>}<button onClick={()=>update({spellGrants:grants.filter((_,n)=>n!==i)})}>Удалить</button></fieldset>)}</section>;
