function HomebrewBrowser({library,query,setQuery,filter,setFilter,open,apply,remove,download}:{library:HomebrewLibrary;query:string;setQuery:(v:string)=>void;filter:string;setFilter:(v:string)=>void;open:(e:HomebrewElement)=>void;apply:(e:HomebrewElement)=>void;remove:(e:HomebrewElement)=>Promise<void>;download:(data:unknown,name:string)=>void}){
 const [sort,setSort]=useState('newest'),[showParts,setShowParts]=useState(false),[source,setSource]=useState('all');
 const owned=new Map<string,string>();for(const parent of library.elements.filter(e=>e.type==='class'||e.type==='subclass')){const owner=parent.type==='subclass'?parent.parentClassId||parent.id:parent.id;for(const rows of Object.values(parent.advancement||{}))for(const row of rows)if(row.id)owned.set(row.id,owner);for(const choice of parent.choices||[])for(const id of choice.from)owned.set(id,owner);}for(const entry of library.elements)if(entry.parentClassId&&entry.type==='ability')owned.set(entry.id,entry.parentClassId);
 const visible=library.elements.filter(e=>{
  const matches=(e.name+' '+e.id+' '+e.tags?.join(' ')+' '+e.summary).toLowerCase().includes(query.toLowerCase());
  return matches&&(filter==='all'||e.type===filter)&&(source==='all'||(source==='example')===(e.source?.kind==='example'))&&(showParts||!owned.has(e.id)||!!query);
 }).sort((a,b)=>sort==='name'?a.name.localeCompare(b.name,'ru'):sort==='type'?a.type.localeCompare(b.type)||a.name.localeCompare(b.name,'ru'):b.updatedAt.localeCompare(a.updatedAt));
 return <><div className="hb-browser-tools"><input aria-label="Поиск Homebrew" placeholder="Название, тег или ID" value={query} onChange={e=>setQuery(e.target.value)}/><Select label="Фильтр Homebrew" value={filter} onChange={setFilter} options={{all:'Все типы',...homebrewTypeLabels}}/><Select label="Сортировка Homebrew" value={sort} onChange={setSort} options={{newest:'Сначала новые',name:'По названию',type:'По типу'}}/><Select label="Происхождение Homebrew" value={source} onChange={setSource} options={{all:'Все',mine:'Мои',example:'Примеры'}}/></div><label><input type="checkbox" checked={showParts} onChange={e=>setShowParts(e.target.checked)}/> Показывать дочерние элементы отдельно</label><p>{visible.length} записей · {library.elements.length} всего. Особенности класса показаны внутри карточки класса.</p><div className="hb-browser-results">{visible.map(e=><article key={e.id} className="hb-library-row"><CatalogIcon id={e.id} kind={e.type==='class'?'class':e.type==='race'?'race':'background'} fallback={e.name} image={e.icon}/><div><small>{homebrewTypeLabels[e.type]}{owned.has(e.id)?' · особенность класса':''}</small><h2>{e.name}</h2><p>{e.summary||e.description.slice(0,125)}</p>{(e.type==='class'||e.type==='subclass')&&<details><summary>Способности и прогрессия ({e.features?.length||0} встроенных)</summary>{e.features?.map(f=><p key={f.id}>{f.level} ур. · {f.name}</p>)}{e.type==='class'&&library.elements.filter(child=>owned.get(child.id)===e.id&&!Object.values(e.advancement||{}).flat().some(r=>r.id===child.id)).map(child=><button key={child.id} onClick={()=>open(child)}>{child.name} · открыть</button>)}{Object.entries(e.advancement||{}).flatMap(([level,rows])=>rows.filter(r=>r.id&&owned.get(r.id)===(e.type==='subclass'?e.parentClassId:e.id)).map(r=>{const child=library.elements.find(x=>x.id===r.id);return child&&<button key={r.id} onClick={()=>open(child)}>{level} ур. · {child.name}</button>}))}</details>}</div><div className="hb-toolbar"><button onClick={()=>open(e)}>Редактировать</button><button onClick={()=>apply(e)}>{e.type==='class'?'Выбрать':'Добавить'}</button><button onClick={()=>download({schemaVersion:2,type:'homebrew-pack',entities:homebrewExportClosure(e,library.elements)},'HeroList-'+e.type+'.json')}>Экспорт</button><details><summary>Ещё</summary><button onClick={()=>{const n=newHomebrew(e.type,e.name+' — копия');open({...e,...n,features:e.features?.map(f=>({...f,id:newHomebrew('ability').id})),resources:e.resources?.map(r=>({...r,id:newHomebrew('resource').id})),attacks:e.attacks?.map(a=>({...a,id:newHomebrew('attack').id})),advancement:{}});}}>Дублировать</button><button onClick={()=>{void remove(e);}}>Удалить</button></details></div></article>)}</div>{!library.elements.length&&<p>Создайте первый элемент или загрузите пример Саванта.</p>}</>;
}
